        /// </summary>
        /// <param name="bettypeId">The bettype identifier.</param>
        /// <returns>The bet type name.</returns>
        public string GetBetTypeNameById(object bettypeId)
        {
            string betType = string.Empty;

            switch ((int)bettypeId)
            {
                case 133:
                    betType = "Home to Win Both Halves";
                    break;
                case 134:
                    betType = "Away to Win Both Halves";
                    break;
                case 135:
                    betType = "Penalty Shootout Yes/No";
                    break;
                case 140:
                    betType = "Highest Scoring Half";
                    break;
                case 141:
                    betType = "Highest Scoring Half Home Team";
                    break;
                case 142:
                    betType = "Highest Scoring Half Away Team";
                    break;
                case 145:
                    betType = "Both Teams to Score";
                    break;
                case 146:
                    betType = "2nd Half Both Teams to Score";
                    break;
                case 147:
                    betType = "Home to Score in Both Halves";
                    break;
                case 148:
                    betType = "Away to Score in Both Halves";
                    break;
                case 149:
                    betType = "Home to Win Either Half";
                    break;
                case 150:
                    betType = "Away to Win Either Half";
                    break;
                case 151:
                    betType = "1st Half Double Chance";
                    break;
                case 152:
                    betType = "Half Time/Full Time Correct Score";
                    break;
                default:
                    betType = CacheRef.GetBettype(bettypeId);
                    break;
            }

            return betType;
        }

